// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.ExplanationOptions;
import org.eclipse.rdf4j.query.explanation.QueryExecutionProfile;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailTupleQuery;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Query-local resource evidence must survive native evaluation and resource closure. */
class LmdbResourceTelemetryTest {

	@TempDir
	Path directory;
	private SailRepository repository;

	@BeforeEach
	void setUp() throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setValueCacheSize(0)
				.setValueOverlayEnabled(false)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER));
		repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			var predicate = values.createIRI("urn:telemetry:label");
			connection.begin();
			for (int i = 0; i < 128; i++) {
				connection.add(values.createIRI("urn:telemetry:s" + i), predicate,
						values.createLiteral("label-with-dictionary-payload-" + i % 16));
			}
			connection.commit();
		}
		LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
		assertThat(store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	void reportsPinnedAdjacencyStateInsteadOfGlobalCounterDeltas() {
		String json = explain("SELECT ?s ?v WHERE { ?s <urn:telemetry:label> ?v }", Explanation.Level.Telemetry);
		assertThat(json).contains("adjacencySnapshotRevision", "adjacencyBaseRevision", "adjacencyOverlayGenerations",
				"PINNED_QUERY_VIEW");
	}

	@Test
	void reportsQueryMemoryAfterGroupStorageHasClosed() {
		try (var connection = repository.getConnection()) {
			var explanation = connection.prepareTupleQuery(
					"SELECT ?v (COUNT(*) AS ?n) WHERE { ?s <urn:telemetry:label> ?v } GROUP BY ?v")
					.explain(Explanation.Level.Telemetry);
			assertThat(explanation.toJson()).contains("memoryPeakReservedBytes", "memoryLimitBytes",
					"memoryReservationRefusals",
					"QUERY_LEDGER");
			var profile = explanation.toGenericPlanNode().getExecutionProfile();
			assertThat(metric(profile, "memoryReservedBytes")).isZero();
			assertThat(profile.stages()).anySatisfy(stage -> {
				assertThat(stage.properties().get("reservationOwner")).isNotNull().isNotEqualTo("unattributed");
				assertThat(stage.metrics().get("memoryPeakReservedBytes").count()).isPositive();
				assertThat(stage.metrics().get("memoryReservedBytes").count()).isZero();
			});
		}
	}

	@Test
	void reportsValueDecodeAndCacheWorkForNativeExpressions() {
		String json = explain("SELECT ?s WHERE { ?s <urn:telemetry:label> ?v FILTER(CONTAINS(LCASE(?v), 'payload')) }",
				Explanation.Level.Telemetry);
		assertThat(json).contains("valueDecodeRequests", "valueDecodeCacheHits", "valueDictionaryReads",
				"valueDictionaryBytes");
	}

	@Test
	void timedExplanationDoesNotEnableResourceCollection() {
		String json = explain("SELECT ?s ?v WHERE { ?s <urn:telemetry:label> ?v }", Explanation.Level.Timed);
		assertThat(json).doesNotContain("memoryPeakReservedBytes", "valueDecodeRequests", "PINNED_QUERY_VIEW");
	}

	@Test
	void explicitValueConsumptionMeasuresLazyNativeOutputDecoding() {
		String text = "SELECT ?v WHERE { ?s <urn:telemetry:label> ?v }";
		QueryExecutionProfile rows;
		QueryExecutionProfile values;
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(text);
			rows = query.explain(Explanation.Level.Telemetry, ExplanationOptions.rows())
					.toGenericPlanNode()
					.getExecutionProfile();
			values = query.explain(Explanation.Level.Telemetry, ExplanationOptions.values())
					.toGenericPlanNode()
					.getExecutionProfile();
		}
		assertThat(rows.properties()).containsEntry("consumptionMode", "rows");
		assertThat(values.properties()).containsEntry("consumptionMode", "values");
		assertThat(metric(rows, "rowsConsumed")).isEqualTo(128);
		assertThat(metric(values, "rowsConsumed")).isEqualTo(128);
		assertThat(metric(values, "valuesRead")).isEqualTo(128);
		assertThat(metric(rows, "valueDecodeRequests")).isZero();
		assertThat(metric(rows, "valueLazyResolutionRequests")).isZero();
		assertThat(metric(values, "valueLazyResolutionRequests")).isGreaterThanOrEqualTo(128);
		assertThat(metric(values, "valueDictionaryReads")).isGreaterThan(metric(rows, "valueDictionaryReads"));
		assertThat(rows.stages())
				.anySatisfy(stage -> assertThat(stage.properties()).containsEntry("measurement", "PINNED_QUERY_VIEW"));
		assertThat(values.stages())
				.anySatisfy(stage -> assertThat(stage.properties()).containsEntry("measurement", "PINNED_QUERY_VIEW"));
	}

	private static long metric(QueryExecutionProfile profile, String name) {
		return profile.stages()
				.stream()
				.filter(stage -> stage.metrics().containsKey(name))
				.findFirst()
				.orElseThrow()
				.metrics()
				.get(name)
				.count();
	}

	private String explain(String text, Explanation.Level level) {
		try (var connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(text);
			return query.explain(level).toJson();
		}
	}
}
